'use strict';
const {money,date,time}=PV;
let state=PV.load(), category='Semua',query='',orderFilter='Semua',adminSearch='',modalState=null,lastFocus=null,nextPayment=null;
let checkoutDraft={name:'',phone:'',mode:'asap',pickup:'',note:''};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={bag:'M6 7h12l2 14H4L6 7Zm3 0V5a3 3 0 0 1 6 0v2',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',list:'M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1',menu:'M4 3v7m3-7v7m3-7v7M4 7h6M7 10v11M18 3v18m0-18c-5 4-5 9 0 9',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3m20 0v-3a4 4 0 0 0-3-3.9M13 3a4 4 0 0 1 0 8 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',wallet:'M3 6h18v14H3zM3 6V3h14v3M16 12h5v4h-5z',leaf:'M20 3C8 2 1 8 6 16s16 0 14-13ZM4 21 16 9',refresh:'M20 7a9 9 0 1 0 1 8M20 2v5h-5',edit:'m4 16-1 5 5-1L21 7l-5-5L4 16Zm9-11 5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',link:'m9 15 6-6m-5-3 2-2a5 5 0 0 1 7 7l-2 2m-3 5-2 2a5 5 0 0 1-7-7l2-2',chat:'M21 11a9 9 0 0 1-9 9 11 11 0 0 1-4-1l-5 2 1-5a9 9 0 1 1 17-5Z',logout:'M9 3H3v18h6m5-14 5 5-5 5m-6-5h12',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-4 10 3 3 5-6',plus:'M12 5v14M5 12h14',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.info}"/></svg>`;}
function art(kind='noodle'){
const defs='<defs><linearGradient id="bowl" x2="0" y2="1"><stop stop-color="#faf4d9"/><stop offset="1" stop-color="#ddd3ae"/></linearGradient></defs>';
let shapes='';
if(['tea','coffee','orange'].includes(kind)){const fill=kind==='coffee'?'#896342':kind==='orange'?'#e9a333':'#bb762e';shapes=`<ellipse cx="150" cy="168" rx="66" ry="12" fill="#594f3620"/><path d="M104 40h92l-12 119q-35 16-69 0Z" fill="#fdf8e7" stroke="#dbd8c5" stroke-width="3"/><path d="M109 65h82l-12 91q-31 10-59 0Z" fill="${fill}"/><ellipse cx="150" cy="66" rx="41" ry="9" fill="${kind==='coffee'?'#c89e6c':'#d69b49'}"/><path d="m166 91 7-72 20-6" stroke="#284f40" stroke-width="7" fill="none"/><path d="m121 82 18-2 3 17-18 3zm30 22 17 1-1 18-18-2zm-25 22 16 1-1 16-16-2" fill="#ffefd988"/><path d="m117 56 8 93" stroke="white" opacity=".45" stroke-width="4"/>`;}
else if(kind==='toast'){shapes='<ellipse cx="150" cy="125" rx="112" ry="50" fill="#e9e5ce"/><ellipse cx="150" cy="119" rx="101" ry="44" fill="#fdfbf0"/><g transform="rotate(-13 150 100)"><path d="M75 72q-10-22 10-27h110q23 9 8 27v66H75Z" fill="#c17f3d"/><path d="M83 71q-7-15 6-18h102q13 6 4 18v58H83Z" fill="#eec788"/><path d="m84 73 110 55M84 91l75 37m-74-19 36 19m0-75 74 38m-37-37 37 19" stroke="#714127" stroke-width="8"/><path d="M139 53v76" stroke="#f9e0ac" stroke-width="4"/></g>';}
else{let noodles='';for(let i=0;i<12;i++)noodles+=`<path d="M${68+i*3} ${75+i*4}q20 -20 40 0t40 0t40 0" stroke="${i%2?'#deaa48':'#efcc70'}" stroke-width="5" fill="none"/>`;
shapes=`<ellipse cx="150" cy="162" rx="101" ry="15" fill="#5a4a2820"/><path d="M41 94q7 80 109 82 102-2 109-82" fill="url(#bowl)"/><ellipse cx="150" cy="92" rx="110" ry="57" fill="#fdf9e8"/><ellipse cx="150" cy="94" rx="98" ry="45" fill="${kind==='soup'?'#b77e3b':kind==='rice'?'#e6d7ac':'#bd9248'}"/>${kind==='rice'?'<ellipse cx="136" cy="91" rx="66" ry="37" fill="#e8d5a3"/><path d="m86 90 12-4m12-10 9 4m-18 22 10-3m8 16 10-5m-2-20 10 3m-2-25 12 4m3 35 8-4m1-17 10 2" stroke="#fff1cc" stroke-width="4"/>':noodles}<path d="m73 65 25-20 16 15-23 16m93 40 26-19 15 12-25 22" fill="#4f8048"/><path d="m72 104 19 10 7-14m104-42-18 14 18 9" fill="#8bad50"/><ellipse cx="174" cy="78" rx="34" ry="25" fill="#fff8dc" transform="rotate(-16 174 78)"/><ellipse cx="176" cy="76" rx="17" ry="14" fill="#eeac32"/><ellipse cx="171" cy="72" rx="7" ry="4" fill="#ffd460"/><path d="m106 60 7 5m18 44 7 3m-45-9 7 1m64 20 5-5m-16-57 5-5" stroke="#6e482d" stroke-width="4"/><path d="m213 33-76 107m85-101-72 107" stroke="#755136" stroke-width="5" stroke-linecap="round"/>`;}
return `<svg viewBox="0 0 300 200" role="img" aria-label="Ilustrasi ${kind.includes('tea')?'minuman':'menu warmindo'}">${defs}${shapes}</svg>`;
}
function food(m){return m.image?`<img src="${esc(m.image)}" alt="${esc(m.name)}">`:art(m.kind);}
function persist(){if(!PV.save(state))toast('Penyimpanan browser penuh/tidak tersedia. Perubahan hanya berlaku selama halaman terbuka.');}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function badge(status){const map={PAID:['Lunas',''],PENDING:['Menunggu bayar','amber'],FAILED:['Gagal','red'],EXPIRED:['Kedaluwarsa','red'],NEW:['Baru','blue'],PREPARING:['Diproses','amber'],COMPLETED:['Sudah diambil',''],CANCELLED:['Dibatalkan','red'],SENT:['WA terkirim · demo',''],QUEUED:['WA menunggu','amber'],UNKNOWN:['WA belum pasti','amber']};const v=map[status]||[status,''];return `<span class="pill ${v[1]}">${esc(v[0])}</span>`;}
function brand(){return '<a class="brand" href="#/menu"><img src="assets/favicon.svg" alt=""><span><strong>Putra Vangkalan<span style="color:#d87542">.</span></strong><small>Warmindo • sejak lapar</small></span></a>';}
function header(active='menu'){return `<div class="demo-bar"><strong>PROTOTYPE</strong> · Menu, harga, nomor, dan transaksi adalah data demo. Tidak ada pembayaran atau WA sungguhan.</div><header class="topbar"><div class="wrap nav">${brand()}<nav class="nav-links" aria-label="Navigasi pelanggan"><a class="${active==='menu'?'active':''}" href="#/menu">Menu</a><a class="${active==='history'?'active':''}" href="#/history">Riwayat order</a><a class="admin-link" href="#/admin">Admin ${icon('arrow')}</a></nav><div class="nav-right"><span class="pill ${state.settings.open?'':'red'}"><span class="dot"></span>${state.settings.open?'Pesanan online buka':'Online tutup'}</span><button class="icon-button" data-action="cart" aria-label="Buka keranjang">${icon('bag')}</button></div></div></header>`;}
function footer(){return `<footer class="footer"><span>© 2026 Warmindo Putra Vangkalan. Dibuat untuk perut yang lapar.</span><span>Ambil sendiri · Tanpa login · <a href="#/admin">Dashboard admin ↗</a></span></footer>`;}
function choices(c){return [c.temp,c.egg?'Tambah telur':null].filter(Boolean).join(' · ');}
function cartLines(){return PV.lines(state).map(c=>`<div class="cart-line"><div class="line-title"><strong>${esc(c.item?.name||'Menu dihapus')}</strong><button class="btn subtle small" data-action="remove-cart" data-id="${c.id}" aria-label="Hapus ${esc(c.item?.name)}">${icon('close')}</button></div><small>${esc(choices(c)||'Porsi reguler')}${!c.item?.available?' · Tidak tersedia':''}</small>${c.note?`<small>“${esc(c.note)}”</small>`:''}<div class="qty-row"><div class="qty"><button data-action="qty" data-id="${c.id}" data-delta="-1" aria-label="Kurangi jumlah">−</button><span>${c.qty}</span><button data-action="qty" data-id="${c.id}" data-delta="1" aria-label="Tambah jumlah">+</button></div><strong>${money(c.unit*c.qty)}</strong></div></div>`).join('');}
function emptyCart(){return `<div class="empty"><div class="empty-icon">${icon('bag')}</div><h3>Perut lapar, keranjang kosong?</h3><p>Pilih menu favoritmu dulu.<br>Yang hangat-hangat sudah menunggu.</p></div>`;}
function cartContent(){return `${state.cart.length?cartLines():emptyCart()}${state.cart.length?`<div class="sum-row total"><span>Total</span><span>${money(PV.total(state))}</span></div><a class="btn primary full" href="#/checkout" data-action="close-link">Lanjut pesan ${icon('arrow')}</a><p class="tiny muted" style="text-align:center;margin-top:11px">Ambil sendiri · Estimasi ${state.settings.estimate} menit</p>`:''}`;}
function menuCards(){const filtered=state.menu.filter(m=>(category==='Semua'||(category==='Favorit'?m.popular:m.category===category))&&m.name.toLowerCase().includes(query.toLowerCase()));return filtered.length?filtered.map(m=>`<article class="menu-card ${m.available?'':'sold'}"><div class="food-image">${m.popular?'<span class="pill">✦ Favorit warung</span>':''}${!m.available?'<span class="pill red">Lagi habis</span>':''}${food(m)}</div><div class="card-body"><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p><div class="card-bottom"><strong>${money(m.price)}${m.egg||m.coldExtra?'<span class="tiny muted"> +</span>':''}</strong><button class="add" data-action="product" data-id="${m.id}" ${!m.available?'disabled':''} aria-label="Pilih ${esc(m.name)}">+</button></div></div></article>`).join(''):'<div class="empty"><h3>Menu belum ketemu</h3><p>Coba kata kunci atau kategori lain.</p></div>';}
function menu(){const qty=state.cart.reduce((s,c)=>s+c.qty,0);return `${header()}<main class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">Tempat singgah, rasa yang akrab</div><h1>Lapar? Pesan dulu.<br><em>Tinggal ambil.</em></h1><p>Mi hangat, teh favorit, dan cerita sehari-hari. Siapkan pesananmu sebelum mampir ke sini.</p><div class="hero-meta"><span>${icon('clock')} Mulai ${state.settings.estimate} menit</span><span>${icon('bag')} Ambil di warung</span></div></div><div class="hero-art">${art('noodle')}<div class="hero-label">Dari dapur, buat kamu.<b>Hangat & akrab.</b></div></div></section>${!state.settings.open?'<div class="info-box warn">Pemesanan online sedang ditutup. Kamu tetap bisa melihat menu dan menyimpan keranjang.</div>':''}<div class="content-grid"><section><div class="section-head"><div><h2>Mau makan apa?</h2><p>Yang sederhana, yang selalu bikin balik lagi.</p></div><div class="search">${icon('search')}<input id="menu-search" placeholder="Cari menu favorit…" aria-label="Cari menu" value="${esc(query)}"></div></div><div class="chips" aria-label="Kategori menu">${['Semua','Favorit',...state.categories].map(c=>`<button class="chip ${category===c?'active':''}" data-action="category" data-value="${esc(c)}">${c==='Favorit'?'✦ ':''}${esc(c)}</button>`).join('')}</div><div id="menu-grid" class="menu-grid">${menuCards()}</div><p class="data-note">Ilustrasi menu dan harga contoh untuk prototype. Foto serta katalog asli bisa diganti lewat admin.</p></section><aside class="cart-panel"><div class="cart-head"><h3>${icon('bag')} Pesananmu</h3><span class="pill">${qty} item</span></div><div class="cart-inner">${cartContent()}</div><div class="cart-foot">${icon('leaf')} Dibuat mendekati waktu ambil. Lebih fresh.</div></aside></div>${footer()}</main>${qty?`<button class="mobile-cart" data-action="cart"><span>${icon('bag')} ${qty} item <small>Lihat pesanan</small></span><strong>${money(PV.total(state))} →</strong></button>`:''}`;}
function itemsHTML(o){return o.items.map(c=>`<div class="order-item"><span class="quantity">${c.qty}×</span><div class="grow"><strong>${esc(c.name)}</strong><small>${esc(choices(c)||'Reguler')}</small>${c.note?`<small>Catatan: ${esc(c.note)}</small>`:''}</div><strong>${money(c.unit*c.qty)}</strong></div>`).join('');}
function cartSummary(){return itemsHTML({items:PV.lines(state).map(c=>({...c,name:c.item?.name||'Menu tidak tersedia'}))});}
function slots(){const now=Date.now(),start=Math.ceil((now+state.settings.estimate*60000)/300000)*300000,end=now+3600000;let out=[];for(let n=start;n<=end;n+=300000)out.push(n);return out;}
function checkout(){if(!state.cart.length)return `${header()}<main class="wrap page"><div class="panel">${emptyCart()}<a class="btn primary full" href="#/menu">Pilih menu dulu</a></div></main>`;const d=checkoutDraft;return `${header()}<main class="wrap page"><a class="back" href="#/menu">${icon('back')} Kembali ke menu</a><div class="page-title"><div class="steps"><span>${icon('check')} Pilih menu</span><span class="active"><b>2</b> Detail & waktu ambil</span><span><b>3</b> Bayar</span></div><h1>Sebentar lagi, beres.</h1><p class="muted small-text">Isi detailnya. Kami siapkan sebelum kamu mampir.</p></div><form id="checkout-form" class="two-col"><div><section class="panel"><div class="panel-title"><span class="number">1</span><h2>Siapa yang mengambil?</h2></div><div class="form-grid"><div class="field"><label for="customer-name">Nama pemesan</label><input id="customer-name" name="name" required maxlength="60" autocomplete="name" placeholder="Nama panggilan juga boleh" value="${esc(d.name)}"></div><div class="field"><label for="customer-phone">Nomor WhatsApp</label><input id="customer-phone" name="phone" required type="tel" autocomplete="tel" placeholder="08xxxxxxxxxx" value="${esc(d.phone)}"></div></div><div class="info-box">${icon('chat')} Penjaga akan menghubungimu lewat WhatsApp ketika makanan siap atau ada perubahan pesanan.</div></section><section class="panel"><div class="panel-title"><span class="number">2</span><h2>Mau diambil kapan?</h2></div><label class="radio-card ${d.mode==='asap'?'selected':''}"><input type="radio" name="mode" value="asap" ${d.mode==='asap'?'checked':''}><span><strong>Secepatnya</strong><small>Perkiraan ${state.settings.estimate} menit setelah pembayaran berhasil.</small></span></label><label class="radio-card ${d.mode==='scheduled'?'selected':''}"><input type="radio" name="mode" value="scheduled" ${d.mode==='scheduled'?'checked':''}><span><strong>Pilih jam pengambilan</strong><small>Maksimal 1 jam ke depan. Disiapkan mendekati waktu ambil.</small></span></label><div class="field" id="scheduled-field" ${d.mode!=='scheduled'?'hidden':''}><label for="pickup-time">Jam pengambilan · WIB</label><select name="pickup" id="pickup-time"><option value="">Pilih waktu</option>${slots().map(s=>`<option value="${s}" ${Number(d.pickup)===s?'selected':''}>${date(s)} WIB</option>`).join('')}</select></div><p class="tiny muted">Waktu ini perkiraan, bukan jaminan. Penjaga mengonfirmasi lewat WA jika ada perubahan.</p></section><section class="panel"><div class="panel-title"><span class="number">3</span><h2>Catatan tambahan</h2></div><textarea name="note" maxlength="300" placeholder="Ada yang perlu penjaga tahu? (opsional)">${esc(d.note)}</textarea></section></div><aside class="panel"><h2 style="font-size:19px;margin-bottom:14px">Ringkasan pesanan</h2>${cartSummary()}<div class="sum-row"><span>Biaya layanan pembayaran</span><span>Ditanggung warung</span></div><div class="sum-row total"><span>Total bayar</span><span>${money(PV.total(state))}</span></div><div class="info-box">${icon('bag')} Ambil sendiri di Warmindo Putra Vangkalan. Tidak ada pengantaran.</div><label class="check-label"><input type="checkbox" required name="agree"> <span>Saya sudah memeriksa nomor WA dan waktu ambil. Nomor digunakan untuk komunikasi pesanan.</span></label><div id="checkout-error" role="alert" class="error-text"></div><button class="btn primary full" type="submit" ${state.settings.open?'':'disabled'}>Lanjut ke pembayaran ${icon('arrow')}</button><p class="tiny muted" style="text-align:center;margin-top:12px">${icon('shield')} Simulasi pembayaran · Tidak ada uang ditagih</p></aside></form>${footer()}</main>`;}
function history(){return `${header('history')}<main class="wrap page"><div class="page-title"><div class="eyebrow">Catatan mampirmu</div><h1>Riwayat order.</h1><p class="small-text muted">Tersimpan di browser ini. Simpan tautan privat untuk membuka pesanan kembali.</p></div>${state.orders.length?state.orders.map(o=>`<article class="history-card"><div class="order-header"><div><strong>${esc(o.number)}</strong><p class="tiny muted">${date(o.created)} WIB</p></div>${badge(o.payment)}</div><p class="small-text" style="margin-top:16px">${o.items.map(c=>`${c.qty}× ${esc(c.name)}`).join(' · ')}</p><div class="bottom"><span class="small-text">${icon('clock')} Ambil ${time(o.pickup)} WIB · <strong>${money(o.total)}</strong></span><a class="btn small" href="#/order/${o.token}">Lihat detail ${icon('arrow')}</a></div></article>`).join(''):`<div class="panel"><div class="empty"><div class="empty-icon">${icon('list')}</div><h3>Belum ada cerita pesanan.</h3><p>Order pertamamu akan muncul di sini.</p></div><a class="btn primary full" href="#/menu">Mulai pilih menu</a></div>`}<div class="info-box">${icon('info')} Prototype menyimpan data hanya di perangkat ini. Tautan tidak membawa data ke perangkat lain. Pada produk final, tautan privat akan mengambil data dari backend.</div>${footer()}</main>`;}
function orderPage(token){const o=state.orders.find(o=>o.token===token);if(!o)return `${header()}<main class="error-page"><h1>Order tidak ditemukan.</h1><p>Tautan tidak valid, atau data demo tidak tersimpan di browser ini.</p><a class="btn primary" href="#/history">Buka riwayat order</a></main>`;const paid=o.payment==='PAID';return `${header('history')}<main class="wrap page"><a class="back" href="#/history">${icon('back')} Riwayat order</a><div class="summary-header"><div class="success-mark">${icon(paid?'check':'clock')}</div><h1>${paid?(o.fulfillment==='CANCELLED'?'Pesanan dibatalkan.':o.fulfillment==='COMPLETED'?'Terima kasih sudah mampir!':'Pesananmu sudah tercatat!'):o.payment==='PENDING'?'Selesaikan pembayaranmu.':'Pembayaran belum berhasil.'}</h1><p>${paid?'Penjaga akan menghubungimu lewat WA. Simpan nomor order untuk pengambilan.':'Ini simulasi. Tidak ada transaksi pembayaran sungguhan.'}</p></div><div class="two-col"><section><div class="pickup-card"><div><small>PERKIRAAN WAKTU AMBIL</small><strong>${date(o.pickup)} WIB</strong><small>Ambil sendiri · Warmindo Putra Vangkalan</small></div>${icon('bag')}</div><div class="panel"><div class="order-header"><h3>${esc(o.number)}</h3>${badge(o.payment)}</div>${itemsHTML(o)}<div class="sum-row total"><span>Total pembayaran</span><span>${money(o.total)}</span></div>${o.note?`<div class="info-box">Catatan: ${esc(o.note)}</div>`:''}${o.refund.status!=='NONE'?`<div class="info-box warn">Refund ${o.refund.status==='PENDING'?'sedang diproses':'dicatat selesai'}: ${money(o.refund.amount)}. ${esc(o.refund.reason)}</div>`:''}</div></section><aside><div class="panel"><h3>Detail pengambilan</h3><div class="sum-row"><span class="muted">Nama</span><strong>${esc(o.name)}</strong></div><div class="sum-row"><span class="muted">WhatsApp</span><span>${esc(o.phone)}</span></div><div class="sum-row"><span class="muted">Pesanan</span>${paid?badge(o.fulfillment):'<span>Menunggu pembayaran</span>'}</div><div class="divider"></div><button class="btn full" data-action="copy-order" data-id="${o.id}">${icon('link')} Salin tautan privat</button><p class="tiny muted" style="margin-top:10px">Jangan membagikan tautan ke orang lain. Pada prototype, tautan hanya bekerja di browser yang menyimpan order.</p>${!paid?`<button class="btn primary full" style="margin-top:15px" data-action="pay" data-id="${o.id}">${o.payment==='PENDING'?'Bayar sekarang':'Coba bayar ulang'} ${icon('arrow')}</button>`:''}</div>${paid?`<div class="info-box ${o.notification==='FAILED'?'warn':''}">${icon('chat')} ${o.notification==='SENT'?'Notifikasi WA ke penjaga disimulasikan berhasil.':'Notifikasi WA demo belum terkirim. Order tetap tersimpan di dashboard penjaga.'}</div>`:''}<a href="#/menu" class="btn full">Pesan lagi</a></aside></div>${footer()}</main>`;}
function login(){return `${header()}<main class="wrap"><div class="login"><div class="panel">${brand()}<h1>Selamat datang, penjaga.</h1><p>Kelola pesanan, menu, dan sif dari satu tempat.</p><div class="info-box warn">Akses demo terbuka. Ini bukan sistem autentikasi produksi.</div><form id="login-form"><div class="field"><label for="admin-name">Nama penjaga</label><input id="admin-name" name="name" value="Aa Iis" required maxlength="40"></div><button class="btn primary full" type="submit">Masuk dashboard demo ${icon('arrow')}</button></form></div></div></main>`;}
function adminShell(tab,body){const nav=[['overview','grid','Ringkasan'],['orders','bag','Pesanan'],['menu','menu','Kelola menu'],['shifts','users','Penjaga & sif'],['settings','settings','Pengaturan']];return `<div class="demo-bar">AREA ADMIN DEMO · Data tersimpan di browser yang sama dengan halaman pelanggan</div><div class="admin-layout"><aside class="sidebar">${brand()}<div class="admin-mobile-title">PUTRA VANGKALAN / ADMIN</div><div class="eyebrow" style="color:#8ca38b">Ruang penjaga</div><nav class="sidebar-nav">${nav.map(([k,i,n])=>`<a href="#/admin/${k}" class="${tab===k?'active':''}">${icon(i)}${n}</a>`).join('')}</nav><div class="sidebar-foot"><a href="#/menu" class="row-gap">${icon('back')} Kembali ke menu</a><button class="btn subtle small" style="color:#b6cbb9;margin-top:16px" data-action="logout">${icon('logout')} Keluar demo</button></div></aside><main class="admin-main"><div class="admin-top"><div class="breadcrumbs">Warmindo / ${esc(nav.find(n=>n[0]===tab)?.[2]||'Admin')}</div><div class="row-gap"><span class="pill ${state.settings.open?'':'red'}">${state.settings.open?'Online buka':'Online tutup'}</span><span class="avatar">${esc((sessionStorage.getItem('pv-admin')||'AI').slice(0,2).toUpperCase())}</span></div></div>${!state.settings.waConnected?'<div class="info-box warn">Koneksi WAHA demo terputus. Periksa pesanan di dashboard dan pulihkan koneksi di Pengaturan.</div>':''}${body}<p class="data-note">Prototype frontend · WAHA, Midtrans, autentikasi, dan sinkronisasi server belum terhubung.</p></main></div>`;}
function adminHeading(title,desc,button=''){return `<div class="admin-heading"><div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`;}
function orderTable(orders){return `<div class="table-wrap"><table><thead><tr><th>Order / pelanggan</th><th>Waktu ambil</th><th>Total</th><th>Status</th><th>Notifikasi</th><th></th></tr></thead><tbody>${orders.length?orders.map(o=>`<tr><td><strong>${esc(o.number)}</strong><small>${esc(o.name)} · ${o.items.reduce((a,c)=>a+c.qty,0)} item</small></td><td>${time(o.pickup)} WIB<small>${date(o.pickup).split('pukul')[0]}</small></td><td>${money(o.total)}</td><td>${badge(o.payment==='PAID'?o.fulfillment:o.payment)}</td><td>${o.payment==='PAID'?badge(o.notification):'—'}</td><td><button class="btn small" data-action="admin-order" data-id="${o.id}">Detail ↗</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty"><h3>Belum ada pesanan di sini</h3><p>Buat order dari halaman pelanggan atau muat contoh pesanan.</p></div></td></tr>'}</tbody></table></div>`;}
function overview(){const paid=state.orders.filter(o=>o.payment==='PAID'),open=paid.filter(o=>!['COMPLETED','CANCELLED'].includes(o.fulfillment)),done=paid.filter(o=>o.fulfillment==='COMPLETED'),failed=paid.filter(o=>o.notification==='FAILED'),sales=paid.filter(o=>o.fulfillment!=='CANCELLED').reduce((a,o)=>a+o.total-(o.refund.status.includes('REFUNDED')?o.refund.amount:0),0);return adminShell('overview',`${adminHeading('Selamat bertugas 👋','Pantau pesanan, siapkan yang hangat, layani yang lapar.',`<button class="btn" data-action="seed-orders">${icon('plus')} Muat contoh order</button>`)}<div class="stats"><div class="stat highlight"><div class="label">PESANAN PERLU DITANGANI ${icon('bag')}</div><strong>${open.length}</strong><small>Order lunas yang belum selesai</small></div><div class="stat"><div class="label">NILAI ORDER AKTIF ${icon('wallet')}</div><strong>${money(sales)}</strong><small>Data demo · bukan settlement gateway</small></div><div class="stat"><div class="label">SUDAH DIAMBIL ${icon('check')}</div><strong>${done.length}</strong><small>Total order selesai dalam demo</small></div><div class="stat"><div class="label">NOTIFIKASI GAGAL ${icon('chat')}</div><strong>${failed.length}</strong><small>${failed.length?'Perlu pemeriksaan dan kirim ulang':'Tidak ada masalah pengiriman demo'}</small></div></div><div class="admin-columns"><section><div class="section-head"><h3>Pesanan terbaru</h3><a class="small-text muted" href="#/admin/orders">Lihat semua ↗</a></div>${orderTable(state.orders.slice(0,5))}</section><aside><div class="panel"><div class="eyebrow">Operasional saat ini</div><h3 style="margin-top:12px">Siap menerima pesanan?</h3><div class="sum-row"><span>Pesanan online</span><button class="toggle ${state.settings.open?'on':''}" data-action="toggle-open" aria-label="Ubah status pesanan online" aria-pressed="${state.settings.open}"></button></div><div class="sum-row"><span>Estimasi persiapan</span><strong>${state.settings.estimate} menit</strong></div><div class="sum-row"><span>Penjaga aktif</span><strong>${esc(state.shifts.find(s=>s.id===state.settings.recipient)?.name||'Belum dipilih')}</strong></div><a href="#/admin/settings" class="btn full small">Atur operasional ${icon('arrow')}</a></div><div class="panel"><div class="eyebrow">Target peluncuran</div><h3 style="margin-top:12px">3 order selesai / hari</h3><p class="small-text muted" style="margin-top:10px">Target minggu kedua. Pengukuran tanggal peluncuran belum diaktifkan pada prototype.</p><div class="info-box">${done.length} order demo sudah ditandai diambil.</div></div></aside></div>`);}
function adminOrders(){let filtered=state.orders.filter(o=>(orderFilter==='Semua'||(orderFilter==='Perlu ditangani'?o.payment==='PAID'&&['NEW','PREPARING'].includes(o.fulfillment):orderFilter==='WA gagal'?o.payment==='PAID'&&o.notification==='FAILED':orderFilter==='Selesai'?o.fulfillment==='COMPLETED':o.payment==='PENDING'))&&`${o.number} ${o.name}`.toLowerCase().includes(adminSearch.toLowerCase()));return adminShell('orders',`${adminHeading('Pesanan online.','Daftar kerja internal. Waktu ambil selalu dalam WIB.',`<button class="btn" data-action="refresh">${icon('refresh')} Refresh</button>`)}<div class="tabs-spread"><div class="chips" style="margin:0">${['Semua','Perlu ditangani','WA gagal','Selesai','Menunggu bayar'].map(f=>`<button class="chip ${orderFilter===f?'active':''}" data-action="order-filter" data-value="${f}">${f}</button>`).join('')}</div><div class="search">${icon('search')}<input id="admin-search" aria-label="Cari pesanan" placeholder="Cari nomor / nama…" value="${esc(adminSearch)}"></div></div><div id="orders-table">${orderTable(filtered)}</div><p class="data-note">${filtered.length} pesanan · Data lokal diperbarui ${time(Date.now())} WIB</p>`);}
function adminMenu(){return adminShell('menu',`${adminHeading('Menu yang bikin balik.','Atur katalog demo, harga, opsi, dan ketersediaan.',`<button class="btn primary" data-action="edit-menu">${icon('plus')} Tambah menu</button>`)}<div class="panel"><div class="section-head" style="margin-bottom:10px"><h3>Kategori menu</h3><button class="btn small" data-action="add-category">${icon('plus')} Kategori</button></div><div class="chips" style="margin:0">${state.categories.map(c=>`<button class="chip" data-action="edit-category" data-value="${esc(c)}">${esc(c)} ${icon('edit')}</button>`).join('')}</div><p class="tiny muted">Klik kategori untuk mengubah nama, urutan, atau menghapus kategori kosong.</p></div><div class="table-wrap"><table><thead><tr><th>Menu</th><th>Kategori</th><th>Harga dasar</th><th>Tersedia</th><th>Aksi</th></tr></thead><tbody>${state.menu.map(m=>`<tr><td><div class="table-food"><div class="food-image">${food(m)}</div><div><strong>${esc(m.name)}</strong><small>${m.egg?'Opsi telur':m.temperatures?.join(' / ')||'Tanpa pilihan'}</small></div></div></td><td>${esc(m.category)}</td><td>${money(m.price)}</td><td><button class="toggle ${m.available?'on':''}" data-action="toggle-menu" data-id="${m.id}" aria-label="Ubah ketersediaan ${esc(m.name)}" aria-pressed="${m.available}"></button></td><td><button class="btn small" data-action="edit-menu" data-id="${m.id}">${icon('edit')} Edit</button></td></tr>`).join('')}</tbody></table></div>`);}
function shifts(){const pending=state.orders.filter(o=>o.payment==='PAID'&&['NEW','PREPARING'].includes(o.fulfillment));return adminShell('shifts',`${adminHeading('Orang yang tepat, sif yang tepat.','Pilih manual penjaga penerima notifikasi pesanan berikutnya.',`<button class="btn primary" data-action="edit-shift">${icon('plus')} Tambah penjaga</button>`)}<div class="two-col"><section class="panel"><h3 style="margin-bottom:20px">Daftar penjaga</h3>${state.shifts.map(s=>`<div class="shift-card ${state.settings.recipient===s.id?'selected':''}"><div><strong>${esc(s.name)}</strong><p>${esc(s.phone)}</p></div><div class="row-gap">${state.settings.recipient===s.id?'<span class="pill">Sif aktif</span>':`<button class="btn small" data-action="activate-shift" data-id="${s.id}">Aktifkan</button>`}<button class="icon-button" data-action="edit-shift" data-id="${s.id}" aria-label="Edit ${esc(s.name)}">${icon('edit')}</button></div></div>`).join('')}<div class="info-box">${icon('info')} Nomor pada data awal adalah contoh. Tidak ada pesan sungguhan yang dikirim.</div></section><aside class="panel"><div class="eyebrow">Serah terima</div><h3 style="margin-top:13px">${pending.length} pesanan belum selesai</h3><p class="small-text muted" style="margin:12px 0">Pergantian sif tidak membatalkan order. Pastikan penjaga berikutnya mengetahui seluruh pesanan ini.</p>${pending.map(o=>`<div class="activity"><div class="bubble">${icon('bag')}</div><div><strong>${esc(o.name)} · ${time(o.pickup)} WIB</strong><p>${esc(o.number)}</p><button class="btn small" style="margin-top:7px" data-action="admin-order" data-id="${o.id}">Lihat pesanan</button></div></div>`).join('')||'<p class="small-text muted">Tidak ada pesanan untuk diserahterimakan.</p>'}</aside></div>`);}
function settings(){return adminShell('settings',`${adminHeading('Atur ritme warung.','Pengaturan memengaruhi halaman pelanggan di browser yang sama.')}<div class="two-col"><section><form class="panel" id="settings-form"><h3 style="margin-bottom:24px">Penerimaan pesanan</h3><div class="sum-row"><span>Pesanan online ${state.settings.open?'buka':'tutup'}</span><button type="button" class="toggle ${state.settings.open?'on':''}" data-action="toggle-open" aria-label="Buka atau tutup online" aria-pressed="${state.settings.open}"></button></div><div class="divider"></div><div class="field"><label for="estimate">Estimasi persiapan (menit)</label><input id="estimate" name="estimate" type="number" min="5" max="60" step="1" required value="${state.settings.estimate}"><small>Berlaku untuk checkout baru. Order yang sudah lunas tidak diubah.</small></div><div class="field"><label for="egg-price">Tambahan telur (Rp)</label><input id="egg-price" name="eggPrice" type="number" min="0" step="500" required value="${state.settings.eggPrice}"></div><button class="btn primary" type="submit">Simpan pengaturan</button></form><section class="panel"><h3>Data prototype</h3><p class="small-text muted" style="margin:13px 0">Reset menghapus seluruh pesanan, katalog yang diedit, dan keranjang demo pada browser ini.</p><button class="btn danger" data-action="reset">${icon('trash')} Reset semua data demo</button></section></section><aside><section class="panel"><h3>Simulator koneksi WAHA</h3><div class="sum-row"><span>Koneksi demo</span><span class="pill ${state.settings.waConnected?'':'red'}">${state.settings.waConnected?'Terhubung':'Terputus'}</span></div><p class="small-text muted">Gunakan simulasi terputus untuk mencoba alur notifikasi gagal setelah pembayaran.</p><button class="btn full" style="margin-top:18px" data-action="toggle-wa">${icon('refresh')} ${state.settings.waConnected?'Simulasikan terputus':'Pulihkan koneksi demo'}</button><div class="info-box warn">Tidak menghubungkan homeserver atau sesi WhatsApp asli. Retry di prototype dijalankan manual dari detail order.</div></section><section class="panel"><h3>Integrasi produksi</h3><div class="activity"><div class="bubble">${icon('wallet')}</div><div><strong>Midtrans</strong><p>Belum terhubung · pembayaran simulasi</p></div></div><div class="activity"><div class="bubble">${icon('chat')}</div><div><strong>WAHA + WEBJS</strong><p>Rencana: homeserver Bang Jan</p></div></div><div class="activity"><div class="bubble">${icon('shield')}</div><div><strong>Backend & autentikasi</strong><p>Belum ada · data localStorage</p></div></div></section></aside></div>`);}
function render(){const route=location.hash.slice(1)||'/menu';let html;if(route.startsWith('/admin')){const name=sessionStorage.getItem('pv-admin');if(!name)html=login();else{const tab=route.split('/')[2]||'overview';html=({overview,orders:adminOrders,menu:adminMenu,shifts,settings}[tab]||overview)();}}else if(route==='/checkout')html=checkout();else if(route==='/history')html=history();else if(route.startsWith('/order/'))html=orderPage(route.split('/')[2]);else html=menu();$('#app').innerHTML=html;document.title=(route.startsWith('/admin')?'Admin · ':route==='/checkout'?'Checkout · ':'')+'Putra Vangkalan';}
function showModal(title,body,wide=false){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h3 id="modal-title">${esc(title)}</h3><button class="icon-button" data-action="close-modal" aria-label="Tutup dialog">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root button')?.focus(),0);}
function closeModal(){ $('#modal-root').innerHTML='';document.body.style.overflow='';modalState=null;lastFocus?.focus?.();}
function productModal(id){const m=state.menu.find(m=>m.id===id);if(!m?.available)return;modalState={type:'product',id,qty:1,egg:false,temp:m.temperatures?.[0]||'',note:''};drawProduct();}
function drawProduct(){const s=modalState,m=state.menu.find(m=>m.id===s.id);showModal(m.name,`<div class="food-image">${food(m)}</div><p class="small-text muted" style="margin-bottom:20px">${esc(m.description)}</p>${m.temperatures?`<label>Pilih sajian</label><div class="option-row">${m.temperatures.map(t=>`<button class="option ${s.temp===t?'selected':''}" data-action="product-temp" data-value="${t}">${t}${t==='Dingin'&&m.coldExtra?` +${money(m.coldExtra)}`:''}</button>`).join('')}</div>`:''}${m.egg?`<label>Tambahkan telur?</label><div class="option-row"><button class="option ${!s.egg?'selected':''}" data-action="product-egg" data-value="no">Tanpa telur</button><button class="option ${s.egg?'selected':''}" data-action="product-egg" data-value="yes">+ Telur ${money(state.settings.eggPrice)}</button></div>`:''}<div class="field"><label for="item-note">Catatan menu <span class="muted">(opsional)</span></label><input id="item-note" maxlength="140" placeholder="Contoh: tidak pedas" value="${esc(s.note)}"></div><div class="modal-actions"><div class="qty"><button data-action="product-qty" data-delta="-1" aria-label="Kurangi jumlah" ${s.qty<=1?'disabled':''}>−</button><strong>${s.qty}</strong><button data-action="product-qty" data-delta="1" aria-label="Tambah jumlah">+</button></div><button class="btn primary" data-action="add-product">Tambah · ${money(PV.price(m,s,state.settings)*s.qty)}</button></div>`);}
function paymentModal(id){const o=state.orders.find(o=>o.id===id);if(!o||o.payment==='PAID')return;showModal('Pembayaran demo',`<div class="payment-demo"><span class="pill amber">SIMULASI · BUKAN MIDTRANS ASLI</span><div class="amount">${money(o.total)}</div><p class="tiny muted">${esc(o.number)}</p><div class="sim-box">${icon('wallet')}<h3>Uji hasil pembayaran</h3><p class="small-text muted" style="margin-top:10px">Pilih hasil untuk melihat perubahan order dan notifikasi. Tidak ada QR atau rekening pembayaran sungguhan.</p></div><button class="btn primary full" data-action="payment-result" data-id="${o.id}" data-value="PAID">${icon('check')} Simulasikan berhasil</button><div class="button-row" style="margin-top:10px"><button class="btn full" data-action="payment-result" data-id="${o.id}" data-value="FAILED">Gagal</button><button class="btn full" data-action="payment-result" data-id="${o.id}" data-value="EXPIRED">Kedaluwarsa</button></div></div>`);}
function adminOrder(id){const o=state.orders.find(o=>o.id===id);if(!o)return;const recipient=state.shifts.find(s=>s.id===o.recipient);showModal('Detail '+o.number,`<div class="order-header"><div><strong>${esc(o.name)}</strong><p class="tiny muted">${esc(o.phone)}</p></div>${badge(o.payment)}</div><div class="info-box">${icon('clock')} Ambil ${date(o.pickup)} WIB</div>${itemsHTML(o)}<div class="sum-row total"><span>Total</span><span>${money(o.total)}</span></div>${o.note?`<p class="small-text">Catatan: ${esc(o.note)}</p>`:''}${o.payment==='PAID'?`<div class="divider"></div><div class="sum-row"><span>Status pesanan</span>${badge(o.fulfillment)}</div><div class="button-row">${o.fulfillment==='NEW'?`<button class="btn primary" data-action="fulfillment" data-id="${o.id}" data-value="PREPARING">Mulai proses</button>`:''}${['NEW','PREPARING'].includes(o.fulfillment)?`<button class="btn primary" data-action="fulfillment" data-id="${o.id}" data-value="COMPLETED">Sudah diambil</button><button class="btn danger" data-action="cancel-order" data-id="${o.id}">Batalkan</button>`:''}</div><div class="divider"></div><div class="sum-row"><span>Notifikasi demo</span>${badge(o.notification)}</div><p class="tiny muted">Penerima: ${esc(recipient?.name||'Penjaga dihapus')} · Percobaan: ${o.attempts}</p><div class="button-row" style="margin-top:12px"><button class="btn small" data-action="wa-preview" data-id="${o.id}">${icon('chat')} Preview pesan</button>${!['COMPLETED','CANCELLED'].includes(o.fulfillment)?`<button class="btn small" data-action="retry-wa" data-id="${o.id}">${icon('refresh')} Kirim ke sif aktif (demo)</button>`:''}</div><div class="divider"></div><h3>Refund manual</h3><p class="tiny muted" style="margin:8px 0">${o.refund.status==='NONE'?'Belum ada refund.':`${esc(o.refund.status)} · ${money(o.refund.amount)} · ${esc(o.refund.reason)}`}</p><button class="btn small" data-action="refund" data-id="${o.id}">Catat / ubah refund</button>`:'<div class="info-box warn">Belum lunas. Jangan menyiapkan pesanan.</div>'}<div class="divider"></div><button class="btn full" data-action="customer-message" data-id="${o.id}">${icon('chat')} Siapkan chat pelanggan (demo)</button><p class="tiny muted" style="margin-top:10px">Prototype hanya menampilkan draft pesan. Tidak membuka atau mengirim WhatsApp.</p>`,true);}
function editMenu(id){const m=state.menu.find(m=>m.id===id)||{name:'',description:'',price:10000,category:state.categories[0],kind:'noodle',available:true};modalState={type:'menu',id,image:m.image||''};showModal(id?'Edit menu':'Tambah menu',`<form id="menu-form"><div class="form-grid"><div class="field"><label>Nama menu<input name="name" value="${esc(m.name)}" required maxlength="70"></label></div><div class="field"><label>Harga dasar (Rp)<input name="price" type="number" min="0" step="500" value="${m.price}" required></label></div></div><div class="field"><label>Deskripsi<textarea name="description" maxlength="180">${esc(m.description)}</textarea></label></div><div class="form-grid"><div class="field"><label>Kategori<select name="category">${state.categories.map(c=>`<option ${c===m.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div class="field"><label>Ilustrasi fallback<select name="kind">${[['noodle','Mi goreng'],['soup','Mi kuah'],['rice','Nasi'],['toast','Roti'],['tea','Teh'],['coffee','Kopi'],['orange','Jeruk']].map(([v,n])=>`<option value="${v}" ${m.kind===v?'selected':''}>${n}</option>`).join('')}</select></label></div></div><div class="field"><label for="menu-photo">Foto menu (opsional)</label><input id="menu-photo" type="file" accept="image/jpeg,image/png,image/webp"><small>Disimpan lokal dan diperkecil. Maksimal berkas awal 5 MB.</small><p id="photo-status" class="tiny muted">${m.image?'Foto sudah tersedia. Pilih berkas untuk mengganti.':'Belum ada foto; menggunakan ilustrasi.'}</p></div><div class="form-grid"><div class="field"><label class="check-label"><input type="checkbox" name="egg" ${m.egg?'checked':''}> Tawarkan tambahan telur</label><label class="check-label"><input type="checkbox" name="hot" ${m.temperatures?.includes('Panas')?'checked':''}> Opsi panas</label><label class="check-label"><input type="checkbox" name="cold" ${m.temperatures?.includes('Dingin')?'checked':''}> Opsi dingin</label></div><div class="field"><label>Tambahan dingin (Rp)<input name="coldExtra" type="number" min="0" step="500" value="${m.coldExtra||0}"></label><label class="check-label"><input type="checkbox" name="popular" ${m.popular?'checked':''}> Favorit warung</label></div></div><div class="button-row"><button class="btn primary" type="submit">Simpan menu</button>${id?`<button class="btn danger" type="button" data-action="delete-menu" data-id="${id}">Hapus menu</button>`:''}</div></form>`,true);}
function editShift(id){const s=state.shifts.find(s=>s.id===id)||{name:'',phone:''};modalState={type:'shift',id};showModal(id?'Edit penjaga':'Tambah penjaga',`<form id="shift-form"><div class="field"><label>Nama penjaga<input name="name" required maxlength="50" value="${esc(s.name)}"></label></div><div class="field"><label>Nomor WhatsApp<input name="phone" type="tel" required value="${esc(s.phone)}" placeholder="08xxxxxxxxxx"></label></div><p id="shift-error" class="error-text"></p><div class="button-row"><button class="btn primary" type="submit">Simpan penjaga</button>${id&&id!==state.settings.recipient?`<button type="button" class="btn danger" data-action="delete-shift" data-id="${id}">Hapus</button>`:''}</div></form>`);}
function categoryModal(value=''){modalState={type:'category',old:value};showModal(value?'Edit kategori':'Tambah kategori',`<form id="category-form"><div class="field"><label>Nama kategori<input name="name" value="${esc(value)}" maxlength="30" required></label></div><div class="field"><label>Urutan tampil<input name="position" type="number" min="1" max="${state.categories.length+(!value?1:0)}" value="${value?state.categories.indexOf(value)+1:state.categories.length+1}" required></label></div><p id="category-error" class="error-text"></p><div class="button-row"><button type="submit" class="btn primary">Simpan kategori</button>${value?'<button type="button" class="btn danger" data-action="delete-category">Hapus kategori</button>':''}</div></form>`);}
function saveDraft(){const f=$('#checkout-form');if(!f)return;const d=new FormData(f);checkoutDraft={name:d.get('name'),phone:d.get('phone'),mode:d.get('mode'),pickup:d.get('pickup'),note:d.get('note')};}
function message(o){return `PESANAN ONLINE — PUTRA VANGKALAN\n${o.number}\nPembayaran: LUNAS (SIMULASI)\nNama: ${o.name}\nWA: ${o.phone}\nAmbil: ${date(o.pickup)} WIB\n\n${o.items.map(c=>`${c.qty}× ${c.name} ${choices(c)} — ${money(c.unit*c.qty)}${c.note?'\nCatatan: '+c.note:''}`).join('\n')}\n\nTotal: ${money(o.total)}\nCatatan: ${o.note||'-'}\nSiapkan mendekati waktu ambil.`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Berhasil disalin.');}catch{showModal('Salin secara manual',`<p class="small-text muted" style="margin-bottom:12px">Akses clipboard tidak tersedia. Pilih dan salin teks ini.</p><textarea readonly rows="6">${esc(text)}</textarea>`);$('#modal-root textarea').select();}}
function confirmModal(title,text,action,id=''){showModal(title,`<p class="small-text muted">${esc(text)}</p><div class="button-row" style="margin-top:22px"><button class="btn" data-action="close-modal">Kembali</button><button class="btn danger" data-action="${action}" data-id="${id}">Ya, lanjutkan</button></div>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,v=b.dataset.value;try{
if(a==='close-modal'||a==='close-link')closeModal();
else if(a==='category'){category=v;render();}
else if(a==='product')productModal(id);
else if(a==='product-temp'||a==='product-egg'||a==='product-qty'){modalState.note=$('#item-note').value;if(a==='product-temp')modalState.temp=v;else if(a==='product-egg')modalState.egg=v==='yes';else modalState.qty=Math.min(20,Math.max(1,modalState.qty+Number(b.dataset.delta)));drawProduct();}
else if(a==='add-product'){const s=modalState,m=state.menu.find(m=>m.id===s.id);if(!m?.available)throw Error('Menu sudah tidak tersedia.');s.note=$('#item-note').value.trim();const existing=state.cart.find(c=>c.menuId===s.id&&c.egg===s.egg&&c.temp===s.temp&&c.note===s.note);if(existing)existing.qty=Math.min(20,existing.qty+s.qty);else state.cart.push({id:PV.uid(),menuId:s.id,qty:s.qty,egg:s.egg,temp:s.temp,note:s.note});persist();closeModal();render();toast(m.name+' masuk keranjang.');}
else if(a==='cart')showModal('Pesananmu',cartContent());
else if(a==='qty'||a==='remove-cart'){const c=state.cart.find(c=>c.id===id);if(!c)return;if(a==='remove-cart')state.cart=state.cart.filter(c=>c.id!==id);else{c.qty=Math.min(20,c.qty+Number(b.dataset.delta));if(c.qty<=0)state.cart=state.cart.filter(c=>c.id!==id);}persist();const modalOpen=!!$('#modal-root').innerHTML;render();if(modalOpen)showModal('Pesananmu',cartContent());}
else if(a==='pay')paymentModal(id);
else if(a==='payment-result'){const o=state.orders.find(o=>o.id===id);PV.pay(state,o,v);persist();closeModal();location.hash='/order/'+o.token;render();toast(v==='PAID'?'Pembayaran demo berhasil. Order tercatat.':'Status pembayaran demo diperbarui.');}
else if(a==='copy-order'){const o=state.orders.find(o=>o.id===id);await copy(location.href.split('#')[0]+'#/order/'+o.token);}
else if(a==='logout'){sessionStorage.removeItem('pv-admin');render();}
else if(a==='toggle-open'){state.settings.open=!state.settings.open;persist();render();toast(state.settings.open?'Pesanan online dibuka.':'Pesanan online ditutup. Order sebelumnya tetap ditangani.');}
else if(a==='toggle-wa'){state.settings.waConnected=!state.settings.waConnected;persist();render();toast('Koneksi WAHA demo '+(state.settings.waConnected?'dipulihkan. Kirim ulang dari detail order.':'diputus.'));}
else if(a==='refresh'){state=PV.load();render();toast('Data lokal diperbarui.');}
else if(a==='order-filter'){orderFilter=v;render();}
else if(a==='admin-order')adminOrder(id);
else if(a==='fulfillment'){const o=state.orders.find(o=>o.id===id);o.fulfillment=v;if(v==='COMPLETED')o.completed=Date.now();persist();render();adminOrder(id);toast('Status pesanan diperbarui.');}
else if(a==='cancel-order'){showModal('Batalkan pesanan',`<form id="cancel-form" data-id="${id}"><p class="small-text muted">Pembayaran tetap tercatat lunas. Pembatalan tidak mentransfer refund secara otomatis.</p><div class="field" style="margin-top:20px"><label>Alasan pembatalan<textarea name="reason" required maxlength="200" placeholder="Contoh: bahan menu habis"></textarea></label></div><button class="btn danger" type="submit">Catat pembatalan</button></form>`);}
else if(a==='retry-wa'){const o=state.orders.find(o=>o.id===id);o.recipient=state.settings.recipient;o.notification=state.settings.waConnected?'SENT':'FAILED';o.attempts++;persist();render();adminOrder(id);toast(state.settings.waConnected?'Pengiriman ulang demo berhasil.':'Demo gagal: koneksi WAHA masih terputus.');}
else if(a==='wa-preview'){const o=state.orders.find(o=>o.id===id);showModal('Preview WA ke penjaga',`<div class="notification-preview">${esc(message(o))}</div><button class="btn full" style="margin-top:17px" data-action="admin-order" data-id="${id}">Kembali ke detail</button>`);}
else if(a==='customer-message'){const o=state.orders.find(o=>o.id===id);showModal('Draft chat pelanggan',`<p class="tiny muted" style="margin-bottom:14px">Ke: ${esc(o.phone)} · Tidak dikirim sungguhan</p><textarea id="customer-draft" rows="5">${esc(`Halo ${o.name}, pesanan ${o.number} dari Warmindo Putra Vangkalan sudah siap diambil. Terima kasih!`)}</textarea><button class="btn primary full" style="margin-top:15px" data-action="copy-draft">Salin draft</button>`);}
else if(a==='copy-draft')await copy($('#customer-draft').value);
else if(a==='refund'){const o=state.orders.find(o=>o.id===id);showModal('Catat refund manual',`<form id="refund-form" data-id="${id}"><div class="info-box warn">Hanya pencatatan demo. Tidak melakukan transfer uang.</div><div class="field"><label>Nominal refund (maks. ${money(o.total)})<input name="amount" type="number" min="1" max="${o.total}" value="${o.refund.amount||o.total}" required></label></div><div class="field"><label>Alasan<textarea name="reason" required maxlength="200">${esc(o.refund.reason)}</textarea></label></div><div class="field"><label>Status<select name="status"><option value="PENDING">Menunggu transfer manual</option><option value="DONE" ${o.refund.status.includes('REFUNDED')?'selected':''}>Sudah ditransfer secara manual</option></select></label></div><button class="btn primary" type="submit">Simpan catatan refund</button></form>`);}
else if(a==='edit-menu')editMenu(id);
else if(a==='toggle-menu'){const m=state.menu.find(m=>m.id===id);m.available=!m.available;persist();render();toast(m.name+(m.available?' tersedia.':' ditandai habis.'));}
else if(a==='delete-menu')confirmModal('Hapus menu?','Menu dihapus dari katalog demo. Snapshot pada order lama tetap tersimpan.','confirm-delete-menu',id);
else if(a==='confirm-delete-menu'){state.menu=state.menu.filter(m=>m.id!==id);persist();closeModal();render();}
else if(a==='add-category')categoryModal();
else if(a==='edit-category')categoryModal(v);
else if(a==='delete-category'){const old=modalState.old;if(state.menu.some(m=>m.category===old)){$('#category-error').textContent='Pindahkan atau hapus menu dalam kategori ini terlebih dahulu.';return;}state.categories=state.categories.filter(c=>c!==old);persist();closeModal();render();}
else if(a==='edit-shift')editShift(id);
else if(a==='activate-shift')confirmModal('Ganti penjaga aktif?','Notifikasi baru akan menuju penjaga ini. Pastikan pesanan yang belum selesai sudah diserahterimakan.','confirm-shift',id);
else if(a==='confirm-shift'){state.settings.recipient=id;persist();closeModal();render();toast('Penjaga aktif diperbarui.');}
else if(a==='delete-shift'){state.shifts=state.shifts.filter(s=>s.id!==id);persist();closeModal();render();}
else if(a==='reset')confirmModal('Reset seluruh data demo?','Seluruh order, perubahan menu, sif, dan keranjang di browser ini akan dihapus.','confirm-reset');
else if(a==='confirm-reset'){state=PV.reset();persist();closeModal();render();toast('Data demo dikembalikan ke awal.');}
else if(a==='seed-orders'){if(state.orders.some(o=>o.seeded)){toast('Contoh order sudah dimuat.');return;}const names=['Raka','Nadia','Dimas','Sari'];for(let i=0;i<4;i++){const m=state.menu.find(m=>m.available)||state.menu[0];if(!m)throw Error('Tambahkan satu menu terlebih dahulu.');const o={id:PV.uid(),token:PV.uid(),number:'DEMO-'+String(104+i),created:Date.now()-(i+1)*600000,pickup:Date.now()+(i+1)*600000,estimate:10,mode:'scheduled',name:names[i],phone:'6281234500010',note:i===1?'Tidak pedas, ya.':'',payment:'PAID',fulfillment:['NEW','PREPARING','COMPLETED','NEW'][i],notification:i===3?'FAILED':'SENT',refund:{status:'NONE',amount:0,reason:''},recipient:state.settings.recipient,attempts:1,items:[{name:m.name,qty:1,unit:m.price,egg:false,temp:'',note:''}],total:m.price,seeded:true};state.orders.push(o);}persist();render();toast('4 contoh pesanan ditambahkan.');}
}catch(err){toast(err.message||'Terjadi kesalahan pada demo.');}});
document.addEventListener('input',e=>{if(e.target.id==='menu-search'){query=e.target.value;$('#menu-grid').innerHTML=menuCards();}if(e.target.id==='admin-search'){adminSearch=e.target.value;const pos=e.target.selectionStart;render();$('#admin-search').focus();$('#admin-search').setSelectionRange(pos,pos);}if(e.target.closest('#checkout-form'))saveDraft();});
document.addEventListener('change',e=>{if(e.target.name==='mode'&&e.target.closest('#checkout-form')){saveDraft();$('#scheduled-field').hidden=e.target.value!=='scheduled';document.querySelectorAll('.radio-card').forEach(el=>el.classList.toggle('selected',el.querySelector('input').checked));}if(e.target.id==='menu-photo'){const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Gunakan JPG, PNG, atau WebP maksimal 5 MB.');e.target.value='';return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,640/img.width);canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);if(modalState?.type==='menu'){modalState.image=canvas.toDataURL('image/jpeg',.75);$('#photo-status').textContent='Foto siap disimpan: '+file.name;}};img.src=reader.result;};reader.readAsDataURL(file);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);try{
if(f.id==='checkout-form'){saveDraft();const o=PV.makeOrder(state,checkoutDraft);persist();nextPayment=o.id;location.hash='/order/'+o.token;render();}
else if(f.id==='login-form'){sessionStorage.setItem('pv-admin',d.get('name').trim());location.hash='/admin/overview';render();}
else if(f.id==='settings-form'){state.settings.estimate=Number(d.get('estimate'));state.settings.eggPrice=Number(d.get('eggPrice'));persist();render();toast('Pengaturan tersimpan.');}
else if(f.id==='menu-form'){const m={id:modalState.id||PV.uid(),name:d.get('name').trim(),description:d.get('description').trim(),price:Number(d.get('price')),category:d.get('category'),kind:d.get('kind'),egg:d.has('egg'),coldExtra:Number(d.get('coldExtra')),popular:d.has('popular'),available:state.menu.find(m=>m.id===modalState.id)?.available??true,image:modalState.image};const temps=[d.has('hot')?'Panas':null,d.has('cold')?'Dingin':null].filter(Boolean);if(temps.length)m.temperatures=temps;if(!m.name)throw Error('Nama menu tidak boleh kosong.');const i=state.menu.findIndex(x=>x.id===m.id);if(i>=0)state.menu[i]=m;else state.menu.push(m);persist();closeModal();render();toast('Menu tersimpan.');}
else if(f.id==='shift-form'){const s={id:modalState.id||PV.uid(),name:d.get('name').trim(),phone:PV.phone(d.get('phone'))};if(!s.name)throw Error('Isi nama penjaga.');const i=state.shifts.findIndex(x=>x.id===s.id);if(i>=0)state.shifts[i]=s;else state.shifts.push(s);persist();closeModal();render();toast('Penjaga tersimpan.');}
else if(f.id==='category-form'){const name=d.get('name').trim(),old=modalState.old;if(!name)throw Error('Isi nama kategori.');if(['Semua','Favorit'].includes(name)||state.categories.some(c=>c===name&&c!==old))throw Error('Nama kategori sudah dipakai atau dicadangkan.');state.categories=state.categories.filter(c=>c!==old);state.categories.splice(Number(d.get('position'))-1,0,name);state.menu.forEach(m=>{if(m.category===old)m.category=name;});persist();closeModal();render();}
else if(f.id==='cancel-form'){const o=state.orders.find(o=>o.id===f.dataset.id);o.fulfillment='CANCELLED';o.cancelReason=d.get('reason').trim();o.refund={status:'PENDING',amount:o.total,reason:o.cancelReason};persist();render();adminOrder(o.id);toast('Pembatalan dicatat. Refund masih menunggu transfer manual.');}
else if(f.id==='refund-form'){const o=state.orders.find(o=>o.id===f.dataset.id),amount=Number(d.get('amount'));if(amount<=0||amount>o.total)throw Error('Nominal refund tidak valid.');o.refund={amount,reason:d.get('reason').trim(),status:d.get('status')==='PENDING'?'PENDING':amount===o.total?'FULL_REFUNDED':'PARTIAL_REFUNDED',updated:Date.now()};persist();render();adminOrder(o.id);toast('Catatan refund disimpan.');}
}catch(err){const target=f.querySelector('[role=alert],.error-text');if(target)target.textContent=err.message;else toast(err.message);}});
document.addEventListener('keydown',e=>{if(!$('#modal-root').innerHTML)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const nodes=[...document.querySelectorAll('#modal-root button:not(:disabled),#modal-root input,#modal-root select,#modal-root textarea,#modal-root a')].filter(n=>!n.hidden);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);if(nextPayment){const id=nextPayment;nextPayment=null;paymentModal(id);}});
window.addEventListener('storage',e=>{if(e.key===PV.KEY){state=PV.load();if(location.hash==='#/checkout'){saveDraft();render();toast('Data menu/pengaturan berubah. Periksa kembali harga dan waktu ambil.');}else render();}});
render();
